(7100524, 1081909, 108580, '<td valign="top">Nicely POV''d, works for me. Does look like she''s pinned under the floorboards.</td>', 'Nicely POV''d, works for me. Does look like she''s pinned under the floorboards.', '2013-09-08 12:27:43.000000', NULL, 1),
(7100649, 1082180, 23484, '<td valign="top">I hate when that happens.</td>', 'I hate when that happens.', '2013-09-08 17:31:09.000000', NULL, 1),
(7100650, 1082093, 23484, '<td valign="top">The grain is fantastic. Very surreal image.</td>', 'The grain is fantastic. Very surreal image.', '2013-09-08 17:31:31.000000', NULL, 1),
(7100651, 1082146, 23484, '<td valign="top">Fire in the sky. Very cool looking.</td>', 'Fire in the sky. Very cool looking.', '2013-09-08 17:32:02.000000', NULL, 1),
(7100652, 1082152, 23484, '<td valign="top">That must be quite the cat.</td>', 'That must be quite the cat.', '2013-09-08 17:32:31.000000', NULL, 1),
(7100653, 1081813, 23484, '<td valign="top">Wow, that is very bizarre looking. Great contrast.</td>', 'Wow, that is very bizarre looking. Great contrast.', '2013-09-08 17:33:43.000000', NULL, 1),
(7100654, 1082174, 23484, '<td valign="top">3 points.</td>', '3 points.', '2013-09-08 17:34:22.000000', NULL, 1),
(7100655, 1082167, 23484, '<td valign="top">It''s hard to argue with that logic.</td>', 'It''s hard to argue with that logic.', '2013-09-08 17:35:26.000000', NULL, 1),
(7100656, 1081453, 23484, '<td valign="top">That is a really cool shot.</td>', 'That is a really cool shot.', '2013-09-08 17:36:04.000000', NULL, 1),
(7100657, 1081826, 23484, '<td valign="top">Another one for the bizarre category. Neat idea.</td>', 'Another one for the bizarre category. Neat idea.', '2013-09-08 17:37:41.000000', NULL, 1),
(7100658, 1082072, 23484, '<td valign="top">Sometimes, those shadows can really fool you.</td>', 'Sometimes, those shadows can really fool you.', '2013-09-08 17:38:11.000000', NULL, 1),
(7100703, 1081916, 62249, '<td valign="top">The lighting in this shot is flat &amp; uninteresting. Since it was an expert editing challenge, perhaps you could have done more with the processing--for example, adjusting the tonal range--to enliven the image.</td>', 'The lighting in this shot is flat & uninteresting. Since it was an expert editing challenge, perhaps you could have done more with the processing--for example, adjusting the tonal range--to enliven the image.', '2013-09-08 19:20:04.000000', NULL, 1),
(7100707, 1082153, 62249, '<td valign="top">This image doesn''t showcase your own photographic work. It looks like it''s just an out-of-focus shot of someone else''s artistic work, perhaps either stained glass or pottery.</td>', 'This image doesn''t showcase your own photographic work. It looks like it''s just an out-of-focus shot of someone else''s artistic work, perhaps either stained glass or pottery.', '2013-09-08 19:26:31.000000', NULL, 1),
(7100708, 1082190, 62249, '<td valign="top">Very funny title.</td>', 'Very funny title.', '2013-09-08 19:27:23.000000', NULL, 1),
